grid = [[5]*24 for _ in range(7)]
markers = [[7,8,9,10,18],[2,8,9,15,19,20],[8,14,20,21,24],[3,5,6,8],[3,5,10,21,24],[8,9,10,13,15],[1,3,5,12,21]]
for r, cols in enumerate(markers):
    for c in cols: grid[r][c-1]=2
# draw between consecutive marker positions along each row and col
for r, cols in enumerate(markers):
    for a,b in zip(cols, cols[1:]):
        for c in range(a+1,b):
            if grid[r][c-1] != 2: grid[r][c-1]=3
for c in range(24):
    rows=[r for r in range(7) if grid[r][c]==2]
    for a,b in zip(rows,rows[1:]):
        for r in range(a+1,b):
            if grid[r][c] != 2: grid[r][c]=3
print('\n'.join(' '.join(map(str,row)) for row in grid))
print([len(row) for row in grid])
